return $input.all().map(item => {

  let text = item.json.semanticContent || "";

  // 1️⃣ Remove markdown headers (###, ##, #)
  text = text.replace(/^#{1,6}\s+/gm, "");

  // 2️⃣ Remove separator lines like ===== or -----
  text = text.replace(/^[=\-]{3,}$/gm, "");

  // 3️⃣ Remove emojis (basic unicode emoji ranges)
  text = text.replace(
    /[\u{1F300}-\u{1FAFF}]/gu,
    ""
  );

  // 4️⃣ Remove markdown bullets (*, -, + at line start)
  text = text.replace(/^[\*\-\+]\s+/gm, "");

  // 5️⃣ Remove excessive line breaks (more than 2)
  text = text.replace(/\n{3,}/g, "\n\n");

  // 6️⃣ Trim extra spaces
  text = text.replace(/[ \t]{2,}/g, " ");

  // 7️⃣ Final trim
  text = text.trim();

  return {
    json: {
      ...item.json,
      semanticContent: text
    }
  };
});

